argv:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type @"
using System;
using System.Text;
using System.Runtime.InteropServices;
public static class W32Check {
  public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowText(IntPtr hWnd, StringBuilder sb, int max);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetClassName(IntPtr hWnd, StringBuilder sb, int max);
}
"@
$script:fileDialog=$false
$cb=[W32Check+EnumWindowsProc]{
 param($h,$l)
 $tsb=New-Object System.Text.StringBuilder 128
 $csb=New-Object System.Text.StringBuilder 64
 [void][W32Check]::GetWindowText($h,$tsb,$tsb.Capacity)
 [void][W32Check]::GetClassName($h,$csb,$csb.Capacity)
 if($tsb.ToString() -eq '開啟' -and $csb.ToString() -eq '#32770'){$script:fileDialog=$true}
 return $true
}
[W32Check]::EnumWindows($cb,[IntPtr]::Zero)|Out-Null

$edge=Get-Process msedge -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1
if($null -eq $edge){throw 'Edge not visible'}
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$media=@()
$buttons=@()
for($i=0;$i -lt $all.Count;$i++){
 $e=$all.Item($i)
 $ct=$e.Current.ControlType.ProgrammaticName
 $r=$e.Current.BoundingRectangle
 if(-not [double]::IsInfinity($r.Y) -and $r.Y -gt 350 -and $r.Y -lt 900){
   if($ct -eq 'ControlType.Image'){
     $media += [pscustomobject]@{name=[string]$e.Current.Name;x=[string]$r.X;y=[string]$r.Y;w=[string]$r.Width;h=[string]$r.Height}
   } elseif($ct -eq 'ControlType.Button'){
     $n=[string]$e.Current.Name
     if($n -match '發佈|移除|刪除|編輯|裁切|媒體|影音|替代|重新'){
       $buttons += [pscustomobject]@{name=$n;enabled=[bool]$e.Current.IsEnabled;x=[string]$r.X;y=[string]$r.Y;w=[string]$r.Width;h=[string]$r.Height}
     }
   }
 }
}
[pscustomobject]@{file_dialog_open=$script:fileDialog;images=$media;buttons=$buttons}|ConvertTo-Json -Depth 5 -Compress
